<template><section v-loading="loading"><div class="toolbar"><el-button type="primary" @click="dialog=true">登记发票</el-button><el-button @click="load">刷新</el-button></div><el-card shadow="never"><el-table :data="records" empty-text="暂无发票"><el-table-column prop="invoice_number" label="发票号码" min-width="150" /><el-table-column prop="seller_name" label="销方" min-width="180" /><el-table-column label="金额" width="130"><template #default="{row}">{{formatMoney(row.amount)}}</template></el-table-column><el-table-column prop="status" label="处理状态" width="130" /><el-table-column prop="verification_status" label="验真状态" width="130" /><el-table-column label="附件" width="90"><template #default="{row}">{{row.attachments.length}}</template></el-table-column><el-table-column label="操作" min-width="300"><template #default="{row}"><el-upload :show-file-list="false" :auto-upload="false" :on-change="onUploadChange(row)"><el-button size="small">上传附件</el-button></el-upload><el-button size="small" @click="ocr(row)">OCR</el-button><el-button size="small" @click="verify(row)">验真</el-button></template></el-table-column></el-table></el-card><el-dialog v-model="dialog" title="登记发票" width="540px"><el-form label-width="90px"><el-form-item label="所属项目"><el-select v-model="form.project_id"><el-option v-for="project in projects" :key="project.id" :label="project.name" :value="project.id" /></el-select></el-form-item><el-form-item label="发票代码"><el-input v-model="form.invoice_code" /></el-form-item><el-form-item label="发票号码"><el-input v-model="form.invoice_number" /></el-form-item><el-form-item label="开票日期"><el-date-picker v-model="form.invoice_date" value-format="YYYY-MM-DD" /></el-form-item><el-form-item label="含税金额"><el-input-number v-model="form.amount" :min="0" :precision="2" /></el-form-item><el-form-item label="税额"><el-input-number v-model="form.tax_amount" :min="0" :precision="2" /></el-form-item><el-form-item label="销方"><el-input v-model="form.seller_name" /></el-form-item><el-form-item label="购买方"><el-input v-model="form.buyer_name" /></el-form-item></el-form><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" @click="create">保存</el-button></template></el-dialog></section></template>
<script setup lang="ts">import{onMounted,reactive,ref}from'vue';import{ElMessage,type UploadFile}from'element-plus';import{financeApi,formatMoney,type FinanceProject,type Invoice}from'@/api/finance';const loading=ref(false),dialog=ref(false),records=ref<Invoice[]>([]),projects=ref<FinanceProject[]>([]);const form=reactive({project_id:'',invoice_code:'',invoice_number:'',invoice_date:'',amount:0,tax_amount:0,seller_name:'',buyer_name:''});async function load(){loading.value=true;try{[records.value,projects.value]=await Promise.all([financeApi.invoices(),financeApi.projects()]);if(!form.project_id)form.project_id=projects.value[0]?.id||''}finally{loading.value=false}}async function create(){await financeApi.createInvoice({...form,invoice_date:form.invoice_date||null});dialog.value=false;ElMessage.success('发票已登记');await load()}async function upload(invoice:Invoice,file?:File){if(!file)return;await financeApi.uploadInvoice(invoice.id,file);ElMessage.success('附件已安全上传');await load()}function onUploadChange(invoice:Invoice){return(file:UploadFile)=>upload(invoice,file.raw)}async function ocr(invoice:Invoice){await financeApi.runOcr(invoice.id);ElMessage.success('OCR处理已完成');await load()}async function verify(invoice:Invoice){await financeApi.verifyInvoice(invoice.id);ElMessage.success('验真处理已完成');await load()}onMounted(load)</script>
<style scoped>.toolbar{display:flex;gap:10px;margin-bottom:16px}</style>
